/**
 *  The command line an app was started with, either this process's own or the
 *  one a second launch forwarded as the page's `singleInstance.activate` event.
 */
export type Activation = {
	arguments: string[],
	workingDirectory: string | null,
};

export type AppIconStyle = "default" | "tinted" | "clear";

export type AppIcons = {
	style: AppIconStyle,
	glyphs: string,
	tinted: IconPaint,
	clear: IconPaint,
};

export type AppState = {
	activation: Activation,
} & Appearance;

export type Appearance = {
	palette: Palette | null,
	typography: Typography,
	motion: Motion,
	corners: Corners,
	locale: Locale,
};

export type ChosenImage = {
	path: string,
	name: string,
	size: number,
};

export type Corners = "rounded" | "square";

export type Drive = {
	id: string,
	block: string,
	device: string,
	name: string,
	model: string,
	serial: string,
	size: number,
	kind: DriveKind,
	removable: boolean,
	canPowerOff: boolean,
	system: boolean,
	readOnly: boolean,
	table: PartitionTable | null,
	extended: Span | null,
	segments: Segment[],
	health: Health | null,
	job: Job | null,
};

export type DriveCheck = {
	method: EncryptionMethod,
	checks: EncryptionCheck[],
	autoUnlock: string,
};

export type DriveEncryption = {
	state: EncryptionState,
	change: EncryptionChange | null,
	progress: number,
	remaining: number,
	autoUnlock: boolean,
	recoveryKeyStored: boolean,
};

export type DriveKind = "nvme" | "ssd" | "hdd" | "usb" | "card" | "optical" | "image";

export type Encryption = {
	kind: string,
	cleartext: Volume | null,
};

export type EncryptionChange = "encrypt" | "decrypt";

export type EncryptionCheck = {
	id: string,
	passed: boolean,
	sentence: string,
};

export type EncryptionMethod = "in-place" | "reformat" | "none";

export type EncryptionState = "encrypting" | "decrypting" | "paused" | "waiting" | "on";

export type Filesystem = "ext4" | "btrfs" | "exfat" | "ntfs" | "vfat";

export type Format = {
	filesystem: Filesystem,
	label: string,
	passphrase?: string | null,
	remember: boolean,
	erase: boolean,
};

export type Health = {
	state: HealthState,
	temperature: number | null,
	powerOnHours: number | null,
	badSectors: number,
	warnings: string[],
	selftest: Selftest,
};

export type HealthState = "good" | "warning" | "failing";

export type IconPaint = {
	plate: string,
	ink: string,
	shade: string,
	rim: number,
};

export type ImageProgress = {
	block: string,
	restoring: boolean,
	copied: number,
	total: number,
	rate: number,
	finished: boolean,
	error: string | null,
};

export type Job = {
	operation: string,
	progress: number | null,
};

export type Launch = {
	target: Target | null,
	image: ChosenImage | null,
	space: string | null,
	system: string | null,
};

export type Locale = {
	languages: string[],
	formats: string,
	fixed: boolean,
};

export type Motion = "full" | "reduced" | "off";

export type MoveProgress = {
	copied: number,
	total: number,
};

export type OtherSystem = {
	id: string,
	kind: SystemKind,
	name: string,
	drive: string,
	size: number,
	parts: SystemPart[],
	kept: number | null,
	startups: SystemStartup[],
	bitlocker: boolean,
	files: string | null,
	folder: string | null,
};

export type Outcome<T> = ({ done: T }) & { wrongKey?: never } | ({ wrongKey: string }) & { done?: never };

export type Palette = {
	accent: string,
	wallpaperAccent: string,
	pureBlack: boolean,
	colors: SchemeColors,
	terminal: SchemeColors,
	appIcons: AppIcons,
	taskbar: import("@luft/ui").TaskbarLooks,
};

export type PartRole = "system" | "reserved" | "recovery" | "meet";

export type PartitionTable = "gpt" | "dos";

export type PlanStep = { kind: "create"; table: string; offset: number; size: number; partitionType: string; name: string; flags: number[]; filesystem: string; label: string } | { kind: "delete"; block: string } | { kind: "place"; block: string; offset: number; size: number } | { kind: "format"; block: string; filesystem: string; label: string } | { kind: "change"; block: string; partitionType?: string | null; name?: string | null; flags?: number[] | null; label?: string | null };

export type Protection = {
	available: boolean,
	autoUnlock: string,
	drives: { [key in string]: DriveEncryption },
};

export type Removed = {
	grown: number,
	needsKey: boolean,
	drive: string,
	free: Space | null,
};

export type SchemeColors = {
	light: { [key in string]: string },
	dark: { [key in string]: string },
};

export type Segment = {
	kind: "volume",
} & Volume | { kind: "free"; offset: number; size: number };

export type Selftest = {
	status: string,
	remaining: number | null,
};

export type Snapshot = {
	drives: Drive[],
};

export type Space = {
	offset: number,
	size: number,
};

export type SpaceItem = { kind: "dir"; name: string; size: number; items: number; done: boolean; inner: number[] } | { kind: "file"; name: string; size: number } | { kind: "other"; count: number; size: number };

export type SpaceUpdate = {
	scan: number,
	root: string,
	view: SpaceView | null,
	scanning: boolean,
	totalItems: number,
	totalSize: number,
	unreadable: number,
	seconds: number,
};

export type SpaceView = {
	path: string[],
	size: number,
	items: number,
	done: boolean,
	children: SpaceItem[],
	hiddenCount: number,
	hiddenSize: number,
};

export type Span = {
	offset: number,
	size: number,
};

export type Startup = {
	directory: string,
	options: string,
};

export type Support = {
	filesystem: Filesystem,
	available: boolean,
	missing: string,
	resize: number,
};

export type SystemKind = "windows" | "linux" | "old-system";

export type SystemPart = {
	block: string,
	device: string,
	size: number,
	role: PartRole,
	label: string,
	filesystem: string,
};

export type SystemStartup = {
	folder: string,
	entries: string[],
};

export type SystemStep = { kind: "startup" } | { kind: "partition"; block: string } | { kind: "old-system" } | { kind: "grow" };

export type Target = {
	drive: string,
	block: string | null,
};

export type Typography = {
	interface: string | null,
	monospace: string | null,
	textScale: number,
};

export type Volume = {
	block: string,
	device: string,
	number: number | null,
	offset: number,
	size: number,
	label: string,
	usage: string,
	fsType: string,
	uuid: string,
	mountPoints: string[],
	used: number | null,
	swapActive: boolean,
	system: boolean,
	partitionType: string | null,
	partitionName: string,
	partitionUuid: string,
	flags: number[],
	logical: boolean,
	encryption: Encryption | null,
	startup: Startup | null,
	job: Job | null,
};
